      const ValueType &val = value.value();
      std::string value_str(reinterpret_cast<const char *>(&val),
                            sizeof(ValueType));
      return indexer->insert(segment_doc_id, value_str);
    }
  } else {
    return indexer->insert_null(segment_doc_id);
  }
  return Status::OK();
}

